function parseJson(value) {
  const text = String(value || '').replace(/```(?:json)?|```/gi, '').trim();
  try {
    return JSON.parse(text);
  } catch {
    const first = text.indexOf('{');
    const last = text.lastIndexOf('}');
    if (first >= 0 && last > first) return JSON.parse(text.slice(first, last + 1));
    return { themes: [] };
  }
}

const meetings = $input.all().map((item, index) => {
  const parsed = parseJson(item.json.choices?.[0]?.message?.content);
  const themes = Array.isArray(parsed.themes)
    ? parsed.themes.map((value) => String(value || '').trim()).filter(Boolean).slice(0, 6)
    : [];

  return {
    meeting: `Meeting ${String(index + 1).padStart(2, '0')}`,
    themes,
  };
});

return [{
  json: {
    meetingCount: meetings.length,
    candidateCount: meetings.reduce((count, item) => count + item.themes.length, 0),
    meetings,
  },
}];

const text = $json.combinedThemes || '';
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  })
    .formatToParts(new Date())
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value])
);
const date = `${parts.year}-${parts.month}-${parts.day}`;
const fileName = `theme-list-model-eval-qwen35-${date}.txt`;

return [{
  json: { fileName, themeCount: $json.themeCount },
  binary: {
    data: {
      data: Buffer.from(text, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName,
    },
  },
}];

const stdout = String($json.stdout || '');
const paths = stdout
  .split(/\r?\n/)
  .map((value) => value.trim())
  .filter(Boolean);

if (!paths.length) {
  return [];
}

return paths.map((filePath) => ({
  json: { filePath }
}));

