function parseJson(value) {
  const text = String(value || '').replace(/```(?:json)?|```/gi, '').trim();
  try {
    return JSON.parse(text);
  } catch {
    const first = text.indexOf('{');
    const last = text.lastIndexOf('}');
    if (first >= 0 && last > first) return JSON.parse(text.slice(first, last + 1));
    throw new Error('The privacy adjudicator did not return valid JSON.');
  }
}

const parsed = parseJson($json.choices?.[0]?.message?.content);
const blockedPatterns = [
  /\bend[- ]of[- ]life\b/i,
  /\baging parent/i,
  /\bfamily crisis\b/i,
  /\bterminal illness\b/i,
  /\bmedical diagnosis\b/i,
  /\breligious upbringing\b/i,
  /\batheis/i,
  /\bemployee performance\b/i,
  /\bdisciplin/i,
  /\bcompensation\b/i,
  /\bsalary\b/i,
  /\bsales pipeline\b/i,
  /\bclient engagement\b/i,
  /\bcontract negotiation/i,
];

const themes = Array.isArray(parsed.themes) ? parsed.themes : [];
const seen = new Set();
const safe = [];

for (const value of themes) {
  const raw = String(value || '').trim();
  const fragments = raw.split(/['"]\s*,\s*['"]/g);

  for (const fragment of fragments) {
    const theme = String(fragment || '')
    .replace(/^[-*•\d.)\s]+/, '')
    .replace(/^['"]+|['"]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
    if (!theme || theme.length > 220) continue;
    if (blockedPatterns.some((pattern) => pattern.test(theme))) continue;

    const key = theme.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    safe.push(theme);
  }
}

const limited = safe.slice(0, 20);

if (!limited.length) {
  throw new Error('The privacy gate returned no public-safe themes.');
}

return [{
  json: {
    themeCount: limited.length,
    combinedThemes: limited.map((theme) => `- ${theme}`).join('\n') + '\n',
  },
}];
